def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([-1]), fmt([0]), fmt([5]), fmt([0, 0, 0]), fmt([-5, -5, -5]), fmt([-10**9, 10**9]), fmt([1, -1, 0, -2, 2])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            lo = rng.choice([-3, -50, -10**9])
            hi = rng.choice([3, 50, 10**9])
            tests.append(fmt([rng.randint(lo, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt([-10**9] * n))
    tests.append(fmt([rng.choice([-1, 0, 1]) for _ in range(n)]))
    tests.append(fmt([0] * n))
    return tests
